import type { AvatarPackage } from '@naavos/schema';

import { renderContext } from '../context.js';
import type { FileMap } from '../index.js';

export function geminiAdapter(pkg: AvatarPackage): FileMap {
  return new Map([
    [
      'GEMINI.md',
      '# Personal Context for Gemini CLI\n\n> Generated by NAAvOS. Recompile to update.\n\n' +
        renderContext(pkg),
    ],
  ]);
}
